    return () => console.log(`cleanup ${name} ${n}`);
  }, [n]);
  return null;
}

function App() {
  const [n, setN] = useState(0);
  return (
    <>
      <button onClick={() => setN(1)}>go</button>
      <Item name="A" n={n} />
      <Item name="B" n={n} />
    </>
  );
