const Chart = memo(function Chart({ options, onSelect }) {
  // ...expensive drawing
  return <canvas onClick={() => onSelect('p1')} />;
});

function Dashboard() {
  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState(null);

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <Chart
        options={{ color: 'red' }}
        onSelect={(p) => setSelected(p)}
      />
    </>
  );
}

explanation:
`memo` skips a re-render only when **every** prop is equal to its previous value, compared one by one with `Object.is` (a shallow comparison). It does not look inside objects.

Each keystroke updates `query`, so `Dashboard` re-renders and evaluates its JSX again:

- `{ color: 'red' }` creates a **new object**, which is not `Object.is`-equal to last render's object.
- `(p) => setSelected(p)` creates a **new function**, also not equal to the previous one.

One changed prop is enough to make `memo` re-render `Chart`, so fixing only one of them changes nothing. Stabilize both:

```jsx
const CHART_OPTIONS = { color: 'red' }; // module level: same object forever

function Dashboard() {
  // ...
  const handleSelect = useCallback((p) => setSelected(p), []);
  return <Chart options={CHART_OPTIONS} onSelect={handleSelect} />;
}
```

If the options depend on props or state, use `useMemo(() => ({ color }), [color])` instead of hoisting. Here `onSelect={setSelected}` also works, because the `useState` setter has a stable identity.

